import React, {useState,useEffect,useRef} from "react";
import htm from "htm";
import "./styles.css";
const html = htm.bind(React.createElement);

const IMG={mwoman:"data:image/jpeg;base64,",mdance:"data:image/jpeg;base64,",hero:"data:image/jpeg;base64,",lounge:"data:image/jpeg;base64,",mural:"data:image/jpeg;base64,",dancers:"data:image/jpeg;base64,",bed:"data:image/jpeg;base64,"};


const CFG={whatsapp:"254700000000",email:"bookings@example.com",api:"/api/bookings"}; /* api: paste the Apps Script web app URL here (see README). Leave empty for the WhatsApp-link fallback. */ /* edit: owner WhatsApp (no +) and email */
const COT=[
 {name:"Nyati House",cap:4,beds:"2 bedrooms",price:11000,img:IMG.lounge,blurb:"A top-floor A-frame home with a double-height living room under a hand-painted Kenyan mural, and a terrace facing the lake."},
 {name:"Chui House",cap:6,beds:"3 bedrooms",price:18000,img:IMG.dancers,blurb:"Our larger penthouse: warm terracotta interiors, a mezzanine landing and a sunrise-facing terrace, with room for the whole family."}];
const COMFORTS=["Hand-painted Kenyan murals","Double-height living rooms","Smart TV and sound bar","Robes and slippers","Hot showers, soft linen","Fast Wi-Fi","Breakfast on request","Secure parking","Garden bonfires","Birdwatching walks"];
const kes=n=>"KES "+n.toLocaleString("en-KE");
const today=new Date().toISOString().slice(0,10);
const nightsOf=(a,b)=>a&&b&&b>a?Math.round((new Date(b)-new Date(a))/864e5):0;
const art=t=>`<svg viewBox="0 0 300 110" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="g${t[0].slice(1)}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${t[0]}"/><stop offset="1" stop-color="${t[1]}"/></linearGradient></defs><rect width="300" height="110" fill="url(#g${t[0].slice(1)})"/><circle cx="215" cy="62" r="17" fill="#F6D58E"/><path d="M0 70 L70 52 L140 66 L210 48 L300 68 V80 H0Z" fill="#2C3A33"/><rect y="76" width="300" height="34" fill="#5E4E58" opacity=".85"/><g fill="#F2B8B0"><ellipse cx="90" cy="88" rx="9" ry="2.5"/><ellipse cx="120" cy="94" rx="11" ry="2.5"/><ellipse cx="160" cy="89" rx="8" ry="2"/></g><rect x="0" y="94" width="300" height="16" fill="#101C15"/><path d="M10 94 V84 H110 V94 M30 84 V94 M55 84 V94 M80 84 V94" stroke="#E8DFC8" stroke-width="2" fill="none"/></svg>`;

/* SAMPLE booked stays: [check-in, check-out). Owner: replace with real bookings. The check-out day itself is free. */
let BOOKED={};
const overlap=(u,a,b)=>(BOOKED[u]||[]).some(([i,o])=>a<o&&b>i);
const isBooked=(u,d)=>(BOOKED[u]||[]).some(([i,o])=>d>=i&&d<o);
function Cal({unit,s,setS,mo}){
 const [y,m]=mo.split("-").map(Number);
 const lead=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7,dim=new Date(Date.UTC(y,m,0)).getUTCDate();
 const cells=[];for(let i=0;i<lead;i++)cells.push(null);
 for(let d=1;d<=dim;d++)cells.push(mo+"-"+String(d).padStart(2,"0"));
 const can=d=>d>=today&&(!isBooked(unit,d)||(s.inn&&!s.out&&d>s.inn&&!overlap(unit,s.inn,d)));
 const pick=d=>setS(o=>{
  if(!o.inn||o.out||d<=o.inn||overlap(unit,o.inn,d))return {...o,inn:d,out:""};
  return {...o,out:d}});
 return html`<div className="cal"><div className="dow">${"MTWTFSS".split("").map((x,i)=>html`<span key=${i}>${x}</span>`)}</div>
 <div className="days">${cells.map((d,i)=>{if(!d)return html`<i key=${"e"+i}/>`;
  const bk=isBooked(unit,d),on=s.inn&&((!s.out&&d===s.inn)||(s.out&&d>=s.inn&&d<=s.out)),ok=can(d);
  return html`<button type="button" key=${d} disabled=${!ok} onClick=${()=>pick(d)} className=${"d"+(bk?" bk":"")+(on?" in":"")+(d<today?" past":"")} aria-label=${d+(bk?", booked":ok?", available":"")}>${+d.slice(8)}</button>`})}</div></div>`}

function Bar({onBook}){return html`<div className="bar"><div className="wrap"><b>Ewalel Cottages</b><div className="r">
 <a className="btn alt" href=${"https://wa.me/"+CFG.whatsapp} target="_blank" rel="noopener">Call: +254 7123456578</a>
 <button className="btn" onClick=${onBook}>Book</button></div></div></div>`}

function Hero(){return html`<header className="hero ph" style=${{backgroundImage:"linear-gradient(180deg,rgba(36,22,16,.2),rgba(36,22,16,.9)),url("+IMG.hero+")"}}>
 <div className="txt"><h1>Penthouse cottages above the flamingo lake.</h1>
 <p>Top-floor A-frame stays on the hill above Lake Elementaita, less than 1 km from the Nairobi–Nakuru highway. Karibu nyumbani.</p>
 <a className="btn" href="#stay">Choose your penthouse</a></div><div className="shuka" aria-hidden="true"></div></header>`}

function Find({s,setS}){
 const set=k=>e=>{const v=e.target.value;setS(o=>({...o,[k]:v,...(k==="inn"&&o.out<=v?{out:""}:{})}))};
 return html`<div className="find">
 <label>Check in<input type="date" min=${today} value=${s.inn} onChange=${set("inn")}/></label>
 <label>Check out<input type="date" min=${s.inn||today} value=${s.out} onChange=${set("out")}/></label>
 <label>Guests<input type="number" min="1" max="6" value=${s.guests} onChange=${set("guests")}/></label></div>`}

const dstr=(d,y)=>new Date(d+"T00:00:00Z").toLocaleDateString("en-GB",{day:"numeric",month:"short",timeZone:"UTC",...(y?{year:"numeric"}:{})});
const addDays=(d,k)=>new Date(new Date(d+"T00:00:00Z").getTime()+k*864e5).toISOString().slice(0,10);
function BookedList({unit,onJump}){
 const L=(BOOKED[unit]||[]).map(([i,o])=>[i,addDays(o,-1)]).filter(([i,l])=>l>=today).sort((a,b)=>a[0]<b[0]?-1:1);
 const yr=today.slice(0,4);
 const lab=([a,b])=>{const y=a.slice(0,4)!==yr||b.slice(0,4)!==yr;if(a===b)return dstr(a,y);
  return a.slice(0,7)===b.slice(0,7)?(+a.slice(8))+"–"+dstr(b,y):dstr(a,y)+" – "+dstr(b,y)};
 return html`<div className="bl"><div className="bh">Upcoming booked days</div>${L.length?L.map(r=>html`<button type="button" key=${r[0]} className="chip bk" onClick=${()=>onJump(r[0]<today?today.slice(0,7):r[0].slice(0,7))}>${lab(r)}</button>`):html`<span className="hint">No bookings yet. Every upcoming date is open.</span>`}</div>`}

function Cards({s,setS,onBook}){
 const [mo,setMo]=useState(today.slice(0,7));
 const n=nightsOf(s.inn,s.out);
 const shift=k=>{const [y,m]=mo.split("-").map(Number);const d=new Date(Date.UTC(y,m-1+k,1));setMo(d.toISOString().slice(0,7))};
 const label=new Date(mo+"-01T00:00:00Z").toLocaleString("en-GB",{month:"long",year:"numeric",timeZone:"UTC"});
 return html`<section id="stay" style=${{paddingTop:24}}><div className="wrap"><h2>Choose your penthouse</h2>
 <p className="hint">Tap your check-in and check-out days on the calendar. Days in red are fully booked.</p>
 <${Find} s=${s} setS=${setS}/>
<div className="mh"><button onClick=${()=>shift(-1)} disabled=${mo<=today.slice(0,7)} aria-label="Previous month">‹</button><span>${label}</span> <button onClick=${()=>shift(1)} aria-label="Next month">›</button></div>
 <div className="cards">${COT.map(c=>{const fits=+s.guests<=c.cap,free=!(n>0&&overlap(c.name,s.inn,s.out));return html`<article key=${c.name} className=${"card"+(fits?"":" off")}>
 <img className="art" src=${c.img} alt=${c.name+" interior"} loading="lazy"/>
 <h3>${c.name}</h3><div className="sleeps">Sleeps ${c.cap}, ${c.beds}, lake-facing terrace</div><p>${c.blurb}</p>
 <div className="price">${kes(c.price)} <small>per night</small></div>
 <${Cal} unit=${c.name} s=${s} setS=${setS} mo=${mo}/>
 <div className="leg"><span><i style=${{background:"var(--red)"}}></i>Booked</span><span><i style=${{background:"var(--green)"}}></i>Your dates</span></div>
 <${BookedList} unit=${c.name} onJump=${setMo}/>
 <div className="tot" role="status">${!fits?"Too small for "+s.guests+" guests":!free?"Not available for these dates":n>0?n+(n===1?" night":" nights")+": "+kes(n*c.price):" "}</div>
 <button className="btn" disabled=${!fits||!free} onClick=${()=>onBook(c.name)}>Book ${c.name}</button></article>`})}</div></div></section>`}

const HILLS=`<svg viewBox="0 0 1200 80" preserveAspectRatio="none" width="100%" height="70" aria-hidden="true"><path style="fill:var(--hill)" d="M0 0H1200V44C1000 78 850 22 640 50S250 82 0 40Z"/><path fill="currentColor" d="M0 0H1200V22C980 58 820 6 600 30S220 60 0 20Z"/></svg>`;
function Murals(){return html`<section className="mur"><div className="hills" dangerouslySetInnerHTML=${{__html:HILLS}}/><div className="wrap"><h2>Walls that tell the story</h2>
 <p className="lead">Hand-painted Kenyan murals of the savanna, the acacia and the dance greet you in every living room.</p>
 <div className="frames"><figure><img src=${IMG.mwoman} alt="Mural of a woman’s profile filled with giraffes and acacia trees" loading="lazy"/><figcaption>The savanna, painted above the lounge</figcaption></figure>
 <figure><img src=${IMG.mdance} alt="Mural of two dancers in black silhouette against the sun" loading="lazy"/><figcaption>Dancers against the setting sun</figcaption></figure></div></div></section>`}

function Gallery({onOpen}){const G=[["lounge","Double-height living room"],["mural","Curved sofa, terracotta accents"],["dancers","Dancers mural above the lounge"],["bed","Bedroom with fresh white linen"]];
 return html`<section style=${{paddingTop:36}}><div className="wrap"><h2>Take a look inside</h2><p className="hint">Swipe to browse. Tap a photo to enlarge it.</p>
 <div className="strip">${G.map(([k,t])=>html`<button key=${k} className="shot" onClick=${()=>onOpen(IMG[k])} aria-label=${"Enlarge photo: "+t}><img src=${IMG[k]} alt=${t} loading="lazy"/><span>${t}</span></button>`)}</div></div></section>`}

function Extras(){return html`<section style=${{paddingTop:8}}><div className="wrap"><h2>Made to feel like home</h2>
 <p className="lead" style=${{marginBottom:16}}>Hosted by family who live nearby. Every guest is greeted in person.</p>
 ${COMFORTS.map(t=>html`<span className="chip" key=${t}>${t}</span>`)}</div></section>`}

function Dialog({name,s,setS,onClose}){
 const [f,setF]=useState({cot:name,n:"",p:"",e:"",x:""});
 const [err,setErr]=useState("");const [sent,setSent]=useState(false);const [busy,setBusy]=useState(false);const [done,setDone]=useState(false);
 const first=useRef();
 useEffect(()=>{const k=e=>e.key==="Escape"&&onClose();document.addEventListener("keydown",k);document.body.style.overflow="hidden";first.current&&first.current.focus();
  return()=>{document.removeEventListener("keydown",k);document.body.style.overflow=""}},[]);
 const c=COT.find(x=>x.name===f.cot),n=nightsOf(s.inn,s.out);
 const set=k=>e=>setF({...f,[k]:e.target.value});
 const sd=k=>e=>{const v=e.target.value;setS(o=>({...o,[k]:v,...(k==="inn"&&o.out<=v?{out:""}:{})}))};
 const text=()=>"New booking request\nPenthouse: "+f.cot+"\nCheck in: "+s.inn+"\nCheck out: "+s.out+"\nNights: "+n+"\nGuests: "+s.guests+"\nName: "+f.n+"\nPhone: "+f.p+(f.e?"\nEmail: "+f.e:"")+(f.x?"\nNotes: "+f.x:"");
 const ok=()=>{if(!s.inn||!s.out||!f.n.trim()||!f.p.trim()){setErr("Please add your dates, name and phone number.");return false}
  if(overlap(f.cot,s.inn,s.out)){setErr(f.cot+" is booked for some of those days. Please pick other dates or the other penthouse.");return false}
  if(+s.guests>c.cap){setErr(c.name+" sleeps "+c.cap+". Please pick a larger penthouse.");return false}
  setErr("");return true};
 const submit=async()=>{if(!ok())return;setBusy(true);
  try{const j=await (await fetch(CFG.api)).json();BOOKED=j;
   if(overlap(f.cot,s.inn,s.out)){setErr("Sorry, those days were just booked. Please choose other dates.");setBusy(false);return}
   const response=await fetch(CFG.api,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({unit:f.cot,checkIn:s.inn,checkOut:s.out,guests:s.guests,name:f.n,phone:f.p,email:f.e,notes:f.x,website:""})});
   if(!response.ok){const failure=await response.json().catch(()=>({}));throw new Error(failure.error||"Booking could not be saved");}
   BOOKED={...BOOKED,[f.cot]:[...(BOOKED[f.cot]||[]),[s.inn,s.out]]};setDone(true);
  }catch(x){setErr(x.message||"We couldn’t send your request. Please try again, or message us on WhatsApp.")}
  setBusy(false)};
 const done_=fn=>()=>{if(ok()){fn();setSent(true)}};
 const wa=done_(()=>window.open("https://wa.me/"+CFG.whatsapp+"?text="+encodeURIComponent(text()),"_blank","noopener"));
 const em=done_(()=>{location.href="mailto:"+CFG.email+"?subject="+encodeURIComponent("Booking request: "+f.cot+", "+s.inn)+"&body="+encodeURIComponent(text())});
 const gc=done_(()=>{const d=x=>x.replace(/-/g,"");window.open("https://calendar.google.com/calendar/render?action=TEMPLATE&text="+encodeURIComponent("Stay at "+f.cot+" (Ewalel Cottages)")+"&dates="+d(s.inn)+"/"+d(s.out)+"&details="+encodeURIComponent(text())+"&location="+encodeURIComponent("Lake Elementaita, Nakuru, Kenya")+"&add="+encodeURIComponent(CFG.email),"_blank","noopener")});
 return html`<div className="ov" onClick=${e=>e.target===e.currentTarget&&onClose()}><div className="dlg" role="dialog" aria-modal="true" aria-label="Book your stay">
 <button className="x" onClick=${onClose} aria-label="Close">×</button><h2>Book your stay</h2>
 <div className="pills" role="group" aria-label="Penthouse">${COT.map(x=>html`<button key=${x.name} aria-pressed=${f.cot===x.name} onClick=${()=>setF({...f,cot:x.name})}>${x.name}</button>`)}</div>
 <form onSubmit=${e=>e.preventDefault()} noValidate>
 <label>Check in<input type="date" min=${today} value=${s.inn} onChange=${sd("inn")}/></label>
 <label>Check out<input type="date" min=${s.inn||today} value=${s.out} onChange=${sd("out")}/></label>
 <p className="sum full">${f.cot}${n>0?": "+n+(n===1?" night":" nights")+", about "+kes(n*c.price):", "+kes(c.price)+" per night"}</p>
 <label>Your name<input ref=${first} value=${f.n} onChange=${set("n")} autoComplete="name"/></label>
 <label>Phone or WhatsApp<input type="tel" value=${f.p} onChange=${set("p")} autoComplete="tel"/></label>
 <label>Guests<input type="number" min="1" max=${c.cap} value=${s.guests} onChange=${sd("guests")}/></label>
 <label>Email (optional)<input type="email" value=${f.e} onChange=${set("e")} autoComplete="email"/></label>
 <label className="full">Notes (optional)<input value=${f.x} onChange=${set("x")} placeholder="Arrival time, celebrations"/></label>
 <p id="msg" className="full" role="alert">${err}</p>
 ${sent&&html`<p className="ok full">Request ready. Send it on WhatsApp or email so we receive it. We reply within a few hours.</p>`}
 ${done?html`<p className="ok full" role="status">Booking request sent. Your request has been saved and the dates are provisionally held. Please contact the owner to arrange confirmation.</p>`:CFG.api?html`<div className="actions full"><button type="button" className="btn" disabled=${busy} onClick=${submit}>${busy?"Sending…":"Confirm booking"}</button></div>`:html`<div className="actions full"><button type="button" className="btn" onClick=${wa}>Send on WhatsApp</button>
 <button type="button" className="btn alt" onClick=${gc}>Add to Google Calendar</button>
 <button type="button" className="btn alt" onClick=${em}>Send by email</button></div>`}</form></div></div>`}

function App(){
 const [s,setS]=useState({inn:"",out:"",guests:2});
 const [open,setOpen]=useState(null);
 const [big,setBig]=useState(null);
 const [,tick]=useState(0);
 useEffect(()=>{if(CFG.api)fetch(CFG.api).then(r=>r.json()).then(j=>{BOOKED=j;tick(t=>t+1)}).catch(()=>{})},[]);
 const quick=()=>setOpen((COT.find(c=>c.cap>=+s.guests)||COT[0]).name);
 return html`<${React.Fragment}><div className="shuka" aria-hidden="true"></div><${Bar} onBook=${quick}/><${Hero}/>
 <${Gallery} onOpen=${setBig}/><${Cards} s=${s} setS=${setS} onBook=${setOpen}/><${Murals}/><${Extras}/>
 <footer><b>Ewalel Cottages</b><p>Lake Elementaita, Nakuru County, Kenya. Less than 1 km from the Nairobi–Nakuru highway.</p><p>WhatsApp +${CFG.whatsapp}  |  ${CFG.email}</p></footer>
 ${big&&html`<div className="ov" onClick=${()=>setBig(null)}><button className="x" style=${{position:"absolute",top:14,right:18,color:"#fff"}} aria-label="Close photo">×</button><img className="lb" src=${big} alt="Enlarged photo"/></div>`}
 ${open&&html`<${Dialog} name=${open} s=${s} setS=${setS} onClose=${()=>setOpen(null)}/>`}<//>`}
export default App;
